<article class="delivery-card <?php echo $delivery['delivery_status'] === 'Pending Assignment' ? 'offer-card' : 'current-delivery'; ?>">
    <div class="delivery-card-top"><div><span class="delivery-order">Order #<?php echo intval($delivery['order_id']); ?></span><span class="badge <?php echo $delivery['delivery_status'] === 'Pending Assignment' ? 'badge-pending' : 'badge-rider'; ?>"><?php echo htmlspecialchars($delivery['delivery_status']); ?></span></div><strong class="delivery-amount">৳<?php echo number_format((float)$delivery['total_amount'], 2); ?></strong></div>
    <div class="delivery-route"><div><span class="route-label">Picked up from</span><strong><?php echo htmlspecialchars($delivery['restaurant_name']); ?></strong><small><?php echo htmlspecialchars($delivery['restaurant_address']); ?></small></div><div><span class="route-label">Deliver to</span><strong><?php echo htmlspecialchars($delivery['customer_name']); ?></strong><small><?php echo htmlspecialchars($delivery['delivery_address']); ?></small></div></div>
    <div class="delivery-meta"><span>☎ <?php echo htmlspecialchars($delivery['customer_phone'] ?? 'N/A'); ?></span><span>Order placed <?php echo htmlspecialchars(date('M d, H:i', strtotime($delivery['created_at']))); ?></span></div>
    <div class="rider-actions" data-delivery="<?php echo intval($delivery['delivery_id']); ?>">
        <?php if ($delivery['delivery_status'] === 'Pending Assignment'): ?><button class="btn btn-primary" data-action="accept">Accept offer</button><?php elseif ($delivery['delivery_status'] === 'Assigned'): ?><button class="btn btn-primary" data-action="pickup">Confirm pickup</button><button class="btn btn-outline-danger" data-action="cancel">Cancel</button><?php elseif ($delivery['delivery_status'] === 'Picked Up'): ?><button class="btn btn-primary" data-action="deliver">Mark delivered</button><button class="btn btn-outline-danger" data-action="cancel">Cancel</button><?php endif; ?><input class="form-control rider-note" maxlength="500" placeholder="Optional delivery note"><a class="contact-link" href="tel:<?php echo htmlspecialchars($delivery['customer_phone'] ?? ''); ?>">☎ Contact customer</a>
    </div>
</article>
